ok = fail = skip = 0
for url in URLS:
    fname = url.split("?")[0].rstrip("/").split("/")[-1]
    out = os.path.join(OUT_DIR, fname)
    if os.path.exists(out) and os.path.getsize(out) > 1000:
        skip += 1
        continue
    try:
        urllib.request.urlretrieve(url, out)
        ok += 1
    except Exception as e:
        fail += 1
        print("失败:", fname, e)

